#include <string>
#include <algorithm>
#include <cctype>
#include <iostream>

int main() {
    std::string s = "MixEd cAsE";

    // Use std::transform for character-level modification
    std::transform(s.begin(), s.end(), s.begin(), 
                   [](unsigned char c) { 
                       return std::toupper(c); 
                   });

    std::cout << s << std::endl; // prints 'MIXED CASE'

    // Custom comparison using std::equal (e.g., case-insensitive check)
    std::string s2 = "mixed case";
    bool eq = std::equal(s.begin(), s.end(), s2.begin(), 
                         [](char c1, char c2) {
                             return std::tolower(c1) == std::tolower(c2);
                         });
}
